import{I as e,o as p,c as t,b6 as l,J as r,w as h,j as a,a as o}from"./chunks/framework.BUXTSoD9.js";const k=JSON.parse('{"title":"اختبار الأم: كيفية التحقق من المتطلبات من خلال مقابلات المستخدمين","description":"مقالة تمهيدية لاختبار الأم موجهة للقراء بدون خبرة مسبقة. تعلم كيفية تجنب الملاحظات المجاملية، وإجراء مقابلات مستخدمين تركز على السلوكيات الحقيقية والحقائق الملموسة والمشاكل القائمة، لتحويل \\"يبدو جيدًا\\" إلى أحكام أكثر موثوقية حول المتطلبات.","frontmatter":{"title":"اختبار الأم: كيفية التحقق من المتطلبات من خلال مقابلات المستخدمين","description":"مقالة تمهيدية لاختبار الأم موجهة للقراء بدون خبرة مسبقة. تعلم كيفية تجنب الملاحظات المجاملية، وإجراء مقابلات مستخدمين تركز على السلوكيات الحقيقية والحقائق الملموسة والمشاكل القائمة، لتحويل \\"يبدو جيدًا\\" إلى أحكام أكثر موثوقية حول المتطلبات."},"headers":[],"relativePath":"ar-sa/stage-1/appendix-mom-test/index.md","filePath":"ar-sa/stage-1/appendix-mom-test/index.md"}'),d={name:"ar-sa/stage-1/appendix-mom-test/index.md"},g=Object.assign(d,{setup(c){const n="حوالي <strong>1.5 ساعة</strong>";return(u,s)=>{const i=e("ChapterIntroduction");return p(),t("div",null,[s[1]||(s[1]=l('<h1 id="اختبار-الأم-كيفية-التحقق-من-المتطلبات-من-خلال-مقابلات-المستخدمين" tabindex="-1">اختبار الأم: كيفية التحقق من المتطلبات من خلال مقابلات المستخدمين <a class="header-anchor" href="#اختبار-الأم-كيفية-التحقق-من-المتطلبات-من-خلال-مقابلات-المستخدمين" aria-label="Permalink to “اختبار الأم: كيفية التحقق من المتطلبات من خلال مقابلات المستخدمين”">​</a></h1><p><a id="top-mom"></a></p><h2 id="مقدمة-الفصل" tabindex="-1">مقدمة الفصل <a class="header-anchor" href="#مقدمة-الفصل" aria-label="Permalink to “مقدمة الفصل”">​</a></h2>',3)),r(i,{duration:n,tags:["مقابلات المستخدمين","التحقق من المتطلبات","أبحاث المستخدمين","دراسة المنتجات"],coreOutput:"مجموعة واحدة من أسئلة المقابلة التي تكشف معلومات حقيقية",expectedOutput:"عدم اعتبار التشجيع المجاملي من المستخدمين كتحقق، واستخدام السلوكيات الحقيقية للحكم على الاتجاه"},{default:h(()=>[...s[0]||(s[0]=[a("p",null,'الكثير من الأشخاص عندما يقومون بأول بحث عن المنتج، يعتقدون أن الأهم هو "التحدث مع شخص ما". لذلك يذهبون لسؤال الأصدقاء والزملاء وحتى أفراد العائلة:',-1),a("ul",null,[a("li",null,"ما رأيك في هذه الفكرة؟"),a("li",null,"إذا كان هناك منتج مثل هذا، هل ستستخدمه؟"),a("li",null,"هل تبدو هذه الميزة جيدة؟")],-1),a("p",null,"غالبًا ما يعطيهم الطرف الآخر ردودًا مشجعة جدًا:",-1),a("ul",null,[a("li",null,"جيد جدًا"),a("li",null,"يبدو مفيدًا"),a("li",null,"أعتقد أنه يمكنك تجربته")],-1),a("p",null,'المشكلة هي أن هذه الإجابات عادةً لا تساعدك في اتخاذ القرار. إنها تشبه المجاملة والدعم، أو رد فعل طبيعي لا يريد أن يحبطك. تعتقد أنك حصلت على "تحقق من السوق"، لكنك في الواقع جمعت فقط مجموعة من المواساة التي يصعب استخدامها في اتخاذ القرار.',-1),a("p",null,[o("طريقة اختبار الأم مصممة خصيصًا لحل هذه المشكلة. إنها تذكرنا: "),a("strong",null,"ليس أن المستخدمين يخدعونك عمدًا، بل طريقة طرحك للأسئلة توجه بطبيعتها الشخص الآخر نحو إجابات لطيفة لكنها غير مفيدة.")],-1)])]),_:1}),s[2]||(s[2]=l(`<div class="info custom-block"><p class="custom-block-title">الحد الأدنى من الإجراءات القياسية</p><p><strong>الهدف</strong>: بعد القراءة، ستكون أكثر وضوحًا حول كيفية التحدث مع المستخدمين، حتى لا تسمع فقط &quot;يبدو جيدًا&quot;، بل تحصل فعلاً على معلومات تساعدك في الحكم على الاتجاه.</p><p><strong>الإجراءات</strong>: غيّر الأسئلة الخمسة التي كنت تنوي طرحها، مع إعطاء الأولوية لأسئلة مثل &quot;متى كانت آخر مرة حدث فيها هذا&quot; و&quot;كيف تعاملت معه في ذلك الوقت&quot;.</p><p><strong>النتيجة</strong>: سيكون من الأسهل عليك التمييز بين الآراء والأدلة الحقيقية التي تدعم القرار.</p><p><strong>الكلمات المفتاحية للانتقال السريع</strong>: <a href="#mom-what">ما هو اختبار الأم</a> · <a href="#mom-principles">المبادئ الأساسية الثلاثة</a> · <a href="#mom-ai">كيف يساعدك الذكاء الاصطناعي</a></p></div><h2 id="سوف-تتعلم-المحتوى-التالي" tabindex="-1">سوف تتعلم المحتوى التالي <a class="header-anchor" href="#سوف-تتعلم-المحتوى-التالي" aria-label="Permalink to “سوف تتعلم المحتوى التالي”">​</a></h2><ol><li>ما المشكلة التي يحلها اختبار الأم حقًا، ولماذا العديد من &quot;أبحاث المستخدمين&quot; لا تحصل فعلاً على معلومات حقيقية</li><li>المبادئ الأساسية القليلة لهذه الطريقة: اسأل أقل عن الآراء، واسأل أكثر عن السلوكيات؛ اسأل أقل عن الافتراضات، واسأل أكثر عن الحقائق</li><li>كيفية تحويل سؤال يسهل الحصول على إجابات إيجابية كاذبة إلى سؤال مقابلة أكثر قيمة</li><li>كيفية استخدام اختبار الأم مع JTBD والتحقق من المتطلبات وحكم MVP معًا</li></ol><p><a id="mom-what"></a></p><h2 id="_1-ما-هو-اختبار-الأم-بالضبط" tabindex="-1"><a href="#top-mom">1. ما هو اختبار الأم بالضبط</a> <a class="header-anchor" href="#_1-ما-هو-اختبار-الأم-بالضبط" aria-label="Permalink to “1. ما هو اختبار الأم بالضبط”">​</a></h2><p>اختبار الأم يأتي من كتاب يحمل نفس الاسم لروب فيتزباتريك. اسمه يبدو وكأنه مزحة، لكنه يصيب الهدف بدقة:</p><p><strong>حتى والدتك، سيكون من الصعب عليها أن تخبرك مباشرة بأن &quot;هذه فكرة سيئة&quot;.</strong></p><p>السبب ليس أنها غير صادقة، بل:</p><ul><li>هي لا تريد أن تؤذيك</li><li>ستشجعك بشكل لا إرادي</li><li>من السهل عليها أن تجيب وفقًا لطريقة تعبيرك</li></ul><p>في الواقع، ليس فقط الأمهات، بل الأصدقاء والزملاء وزملاء الدراسة السابقين، وحتى الكثير من الغرباء، عندما يواجهون فكرة منتجك، غالبًا ما يعطون &quot;ملاحظات إيجابية&quot; مماثلة. هذا لا يعني أن الطلب موجود فعلاً، بل يعني فقط أنك صغت السؤال بطريقة يسهل الحصول على إجابات لطيفة.</p><p>لذلك، النقطة المهمة في اختبار الأم ليست أبدًا &quot;لا تسأل والدتك&quot;، بل:</p><p><strong>لا تصغ سؤالك بطريقة يجيب فيها أي شخص وفقًا لما تريده.</strong></p><p>ما تريد هذه الطريقة تعليمه حقًا هو كيفية الحصول من خلال المحادثة على معلومات أقرب إلى المتطلبات الحقيقية، بدلاً من جمع مجموعة من التعليقات التي تجعلك تشعر بالرضا.</p><h2 id="_2-ما-هي-المشكلة-الأساسية-التي-يحلها" tabindex="-1">2. ما هي المشكلة الأساسية التي يحلها <a class="header-anchor" href="#_2-ما-هي-المشكلة-الأساسية-التي-يحلها" aria-label="Permalink to “2. ما هي المشكلة الأساسية التي يحلها”">​</a></h2><p>اختبار الأم يحل بشكل أساسي وهمًا معرفيًا شائعًا جدًا:</p><p><strong>اعتبار الملاحظات الإيجابية المجاملية كمتطلبات حقيقية.</strong></p><p>على سبيل المثال، إذا سألت:</p><ul><li>ما رأيك في فكرة هذا التطبيق؟</li><li>إذا صنعت أداة بالذكاء الاصطناعي تساعدك في كتابة سيرتك الذاتية، هل ستستخدمها؟</li><li>هل هذه الميزة ذات قيمة؟</li></ul><p>الخاصية المشتركة لهذه الأسئلة هي:</p><ul><li>أنها جميعًا تسأل عن &quot;الآراء&quot;</li><li>أنها جميعًا تحمل تلميحًا</li><li>أنها جميعًا تتحدث عن مستقبل لم يحدث بعد</li></ul><p>وإجابات الناس عن &quot;الآراء&quot; و&quot;الافتراضات المستقبلية&quot; عادةً غير مستقرة. الكثير من الأشخاص يبالغون في تقدير اهتمامهم، يبالغون في تقدير قدرتهم على التنفيذ، ويبالغون في تقدير رغبتهم المستقبلية في الشراء.</p><p>لذلك يذكرك اختبار الأم:</p><ul><li>لا تثق كثيرًا في تقييم الآخرين لفكرتك</li><li>لا تثق كثيرًا في توقعات الآخرين للسلوك المستقبلي</li><li>حاول العودة إلى السلوكيات الحقيقية التي حدثت بالفعل للمستخدمين</li></ul><p>لأنه مقارنة بـ &quot;هل ستستخدم&quot;، &quot;كيف تعاملت مع هذه المشكلة في المرة الأخيرة&quot; غالبًا ما يكون أقرب إلى الحقيقة.</p><p><a id="mom-principles"></a></p><h2 id="_3-المبادئ-الأساسية-الثلاثة" tabindex="-1"><a href="#top-mom">3. المبادئ الأساسية الثلاثة</a> <a class="header-anchor" href="#_3-المبادئ-الأساسية-الثلاثة" aria-label="Permalink to “3. المبادئ الأساسية الثلاثة”">​</a></h2><p>إذا كنت تريد فقط تذكر الأجزاء الأهم أولاً، يمكنك البدء بالمبادئ الثلاثة التالية.</p><h3 id="_3-1-تحدث-أقل-عن-فكرتك،-وتحدث-أكثر-عن-التجارب-الحقيقية-السابقة-للمستخدم" tabindex="-1">3.1 تحدث أقل عن فكرتك، وتحدث أكثر عن التجارب الحقيقية السابقة للمستخدم <a class="header-anchor" href="#_3-1-تحدث-أقل-عن-فكرتك،-وتحدث-أكثر-عن-التجارب-الحقيقية-السابقة-للمستخدم" aria-label="Permalink to “3.1 تحدث أقل عن فكرتك، وتحدث أكثر عن التجارب الحقيقية السابقة للمستخدم”">​</a></h3><p>العديد من المقابلات غير الفعالة تبدأ بشرح الحل الخاص بك، وشرح مدى حماسك، وشرح المنتج الذي تخطط لصنعه. المشكلة هي أنه بمجرد أن تتحدث كثيرًا، يتحول الطرف الآخر بسهولة إلى حالة &quot;مساعدتك&quot; و&quot;تشجيعك&quot;.</p><p>في المقابل، الطريقة الأفضل هي التركيز على تجارب الطرف الآخر:</p><ul><li>متى كانت آخر مرة واجهت فيها هذه المشكلة؟</li><li>ماذا كنت تفعل في ذلك الوقت؟</li><li>كيف تعاملت معها في النهاية؟</li><li>أي خطوة كانت الأكثر إزعاجًا؟</li></ul><p>ستجد أن هذه الأسئلة تعيد المحادثة بشكل أكثر طبيعية إلى الواقع، بدلاً من البقاء في التفضيلات المتخيلة.</p><h3 id="_3-2-اسأل-أقل-عن-الآراء-المجردة،-واسأل-أكثر-عن-الحقائق-الملموسة" tabindex="-1">3.2 اسأل أقل عن الآراء المجردة، واسأل أكثر عن الحقائق الملموسة <a class="header-anchor" href="#_3-2-اسأل-أقل-عن-الآراء-المجردة،-واسأل-أكثر-عن-الحقائق-الملموسة" aria-label="Permalink to “3.2 اسأل أقل عن الآراء المجردة، واسأل أكثر عن الحقائق الملموسة”">​</a></h3><p>&quot;أعتقد أن هذه الميزة جيدة&quot; &quot;يبدو جيدًا&quot; &quot;يبدو مفيدًا بعض الشيء&quot;، هذه التعبيرات مجردة جدًا ويصعب توجيه قرارات المنتج.</p><p>المعلومات الأكثر قيمة عادةً تبدو هكذا:</p><ul><li>الأسبوع الماضى قضيت ساعتين في التعامل مع هذه المشكلة</li><li>أنا أستخدم Excel و WeChat للتغلب عليها</li><li>الشهر الماضى أنفقت المال بالفعل على أداة مشابهة</li><li>أكثر ما أخشاه هو ارتكاب الخطأ، وليس البطء</li></ul><p>هذه هي المعلومات الحقيقية التي تساعدك في الحكم على قوة المشكلة وتكرارها وإمكانية الدفع.</p><h3 id="_3-3-اسأل-أقل-عن-الحل-الذي-يريده-المستخدم،-وانظر-أكثر-في-كيفية-حل-المشكلة-حاليًا" tabindex="-1">3.3 اسأل أقل عن الحل الذي يريده المستخدم، وانظر أكثر في كيفية حل المشكلة حاليًا <a class="header-anchor" href="#_3-3-اسأل-أقل-عن-الحل-الذي-يريده-المستخدم،-وانظر-أكثر-في-كيفية-حل-المشكلة-حاليًا" aria-label="Permalink to “3.3 اسأل أقل عن الحل الذي يريده المستخدم، وانظر أكثر في كيفية حل المشكلة حاليًا”">​</a></h3><p>المستخدمون جيدون في وصف مشاكلهم، لكنهم ليسوا بالضرورة جيدين في تصميم الحلول.</p><p>إذا سألت:</p><ul><li>هل تريد ذكاءً اصطناعيًا يساعدك تلقائيًا في هذا؟</li><li>هل تعتقد أن إضافة ميزة ذكية ستساعد؟</li></ul><p>ما تحصل عليه عادةً هو موقف غامض تجاه حل معين، وليس الطلب نفسه.</p><p>الأسئلة الأفضل هي:</p><ul><li>ما الطريقة التي تستخدمها حاليًا للتعامل مع هذه المشكلة؟</li><li>لماذا اخترت هذه الطريقة؟</li><li>ما الذي لا يكون جيدًا بما فيه الكفاية فيها؟</li></ul><p>رؤية البدائل الحالية غالبًا ما تكون أهم من السؤال المباشر &quot;ماذا تريد&quot;.</p><h2 id="_4-لماذا-يعطي-الناس-دائمًا-إجابات-لطيفة-لكنها-غير-مفيدة" tabindex="-1">4. لماذا يعطي الناس دائمًا إجابات لطيفة لكنها غير مفيدة <a class="header-anchor" href="#_4-لماذا-يعطي-الناس-دائمًا-إجابات-لطيفة-لكنها-غير-مفيدة" aria-label="Permalink to “4. لماذا يعطي الناس دائمًا إجابات لطيفة لكنها غير مفيدة”">​</a></h2><p>إذا كنت تستطيع فهم هذا الأمر، ستقل أخطاء الحكم كثيرًا عند إجراء المقابلات.</p><h3 id="_4-1-الناس-يحافظون-على-الأدب-بشكل-لا-إرادي" tabindex="-1">4.1 الناس يحافظون على الأدب بشكل لا إرادي <a class="header-anchor" href="#_4-1-الناس-يحافظون-على-الأدب-بشكل-لا-إرادي" aria-label="Permalink to “4.1 الناس يحافظون على الأدب بشكل لا إرادي”">​</a></h3><p>خاصة عندما يكون لدى محدثك علاقة بك، سيكون من الصعب عليه أن يقول مباشرة:</p><ul><li>هذا الاتجاه لا يبدو جيدًا</li><li>أنا لن أستخدمه أبدًا</li><li>هذه المشكلة ليست مهمة جدًا بالنسبة لي</li></ul><p>سيقول على الأرجح &quot;جيد&quot; &quot;يمكن تجربته عندما تتاح الفرصة&quot;.</p><h3 id="_4-2-الناس-يبالغون-في-تقدير-أنفسهم-المستقبلية" tabindex="-1">4.2 الناس يبالغون في تقدير أنفسهم المستقبلية <a class="header-anchor" href="#_4-2-الناس-يبالغون-في-تقدير-أنفسهم-المستقبلية" aria-label="Permalink to “4.2 الناس يبالغون في تقدير أنفسهم المستقبلية”">​</a></h3><p>الكثير من الناس يؤمنون بصدق أنهم في المستقبل سيكونون:</p><ul><li>أكثر انضباطًا</li><li>أكثر استعدادًا للتعلم</li><li>أكثر استعدادًا للدفع</li><li>أكثر استعدادًا لتجربة أدوات جديدة</li></ul><p>لذلك جملة &quot;إذا كان متاحًا فأعتقد أنني سأستخدمه&quot; غالبًا لا تساوي الاستخدام الفعلي في المستقبل.</p><h3 id="_4-3-طريقة-طرحك-للأسئلة-توجه-الإجابات-نفسها" tabindex="-1">4.3 طريقة طرحك للأسئلة توجه الإجابات نفسها <a class="header-anchor" href="#_4-3-طريقة-طرحك-للأسئلة-توجه-الإجابات-نفسها" aria-label="Permalink to “4.3 طريقة طرحك للأسئلة توجه الإجابات نفسها”">​</a></h3><p>عندما تسأل:</p><ul><li>هل فكرتي جيدة؟</li><li>هل هذه الميزة مفيدة جدًا بالنسبة لك؟</li></ul><p>أنت في الواقع تضع &quot;الإجابة الصحيحة&quot; سرًا في السؤال.</p><p>هذا هو السبب في أن اختبار الأم يؤكد بشكل خاص: <strong>لا تحول المقابلة إلى بحث عن الموافقة.</strong></p><h2 id="_5-مقارنة-مباشرة-أي-الأسئلة-تفشل-بسهولة-وأيها-أكثر-قيمة" tabindex="-1">5. مقارنة مباشرة: أي الأسئلة تفشل بسهولة وأيها أكثر قيمة <a class="header-anchor" href="#_5-مقارنة-مباشرة-أي-الأسئلة-تفشل-بسهولة-وأيها-أكثر-قيمة" aria-label="Permalink to “5. مقارنة مباشرة: أي الأسئلة تفشل بسهولة وأيها أكثر قيمة”">​</a></h2><p>هذه المقارنات يستخدمها كل مبتدئ تقريبًا.</p><table tabindex="0"><thead><tr><th>الأسئلة التي تفشل بسهولة</th><th>الأسئلة الأكثر قيمة</th></tr></thead><tbody><tr><td>ما رأيك في فكرتي؟</td><td>متى كانت آخر مرة واجهت فيها هذه المشكلة؟</td></tr><tr><td>إذا كان هناك هذا المنتج هل ستستخدمه؟</td><td>كيف تتعامل مع هذا الأمر حاليًا؟</td></tr><tr><td>هل أنت مستعد للدفع مقابل هذه الميزة؟</td><td>هل أنفقت المال على هذه المشكلة في المرة السابقة؟ على ماذا؟</td></tr><tr><td>هل تعتقد أن هذه الميزة مهمة؟</td><td>أي خطوة في هذه العملية هي الأكثر إزعاجًا والأبطأ والأقل راحة؟</td></tr><tr><td>هل تريد ذكاءً اصطناعيًا يساعدك تلقائيًا؟</td><td>لماذا لم تجد حلاً أفضل حتى الآن؟</td></tr></tbody></table><p>ما هو مهم في هذا الجدول ليس الجمل المحددة، بل الاتجاه وراءها:</p><ul><li>من الآراء إلى الحقائق</li><li>من المستقبل إلى الماضي</li><li>من حلولك إلى مشاكل المستخدم</li></ul><h2 id="_6-إيقاع-مقابلة-يمكن-استخدامه-حتى-من-قبل-المبتدئين" tabindex="-1">6. إيقاع مقابلة يمكن استخدامه حتى من قبل المبتدئين <a class="header-anchor" href="#_6-إيقاع-مقابلة-يمكن-استخدامه-حتى-من-قبل-المبتدئين" aria-label="Permalink to “6. إيقاع مقابلة يمكن استخدامه حتى من قبل المبتدئين”">​</a></h2><p>إذا كنت تريد أن تذهب للتحدث مع شخص ما الآن، يمكنك اتباع هذا التسلسل مباشرة.</p><h3 id="_6-1-الافتتاح-اشرح-أنك-تتعلم،-وليس-تبيع" tabindex="-1">6.1 الافتتاح: اشرح أنك تتعلم، وليس تبيع <a class="header-anchor" href="#_6-1-الافتتاح-اشرح-أنك-تتعلم،-وليس-تبيع" aria-label="Permalink to “6.1 الافتتاح: اشرح أنك تتعلم، وليس تبيع”">​</a></h3><p>على سبيل المثال:</p><blockquote><p>أنا أدرس مؤخرًا كيف يتعامل الناس مع هذا النوع من المشاكل، وأريد أن أفهم الوضع الحقيقي أولاً، أنا لست هنا لبيع شيء.</p></blockquote><p>هذا التعبير يجعل من الأسهل على الطرف الآخر التخلي عن العبء النفسي &quot;يجب أن أعطيك ملاحظات إيجابية&quot;.</p><h3 id="_6-2-ابدأ-من-آخر-تجربة-حقيقية" tabindex="-1">6.2 ابدأ من آخر تجربة حقيقية <a class="header-anchor" href="#_6-2-ابدأ-من-آخر-تجربة-حقيقية" aria-label="Permalink to “6.2 ابدأ من آخر تجربة حقيقية”">​</a></h3><p>يمكنك البدء بأسئلة من هذا النوع:</p><ul><li>متى كانت آخر مرة واجهت فيها هذه المشكلة؟</li><li>ماذا حدث في ذلك الوقت؟</li><li>ما كان رد فعلك الأول وكيف تعاملت معه؟</li></ul><p>بمجرد أن تدخل المحادثة في أحداث محددة، تتحسن جودة المعلومات عادةً بشكل ملحوظ.</p><h3 id="_6-3-اطرح-أسئلة-متابعة-حول-السلوك-والتكلفة-والبدائل" tabindex="-1">6.3 اطرح أسئلة متابعة حول السلوك والتكلفة والبدائل <a class="header-anchor" href="#_6-3-اطرح-أسئلة-متابعة-حول-السلوك-والتكلفة-والبدائل" aria-label="Permalink to “6.3 اطرح أسئلة متابعة حول السلوك والتكلفة والبدائل”">​</a></h3><p>استمر في السؤال:</p><ul><li>ما الطريقة التي تستخدمها حاليًا للحل؟</li><li>ما أكثر شيء غير مريح في هذه الطريقة؟</li><li>كم من الوقت أو المال أو الجهد أنفقت على هذا؟</li><li>هل جربت طرقًا أخرى؟ لماذا لم تستمر في استخدامها؟</li></ul><h3 id="_6-4-أخيرًا-احكم-على-الألم-والأولوية" tabindex="-1">6.4 أخيرًا احكم على الألم والأولوية <a class="header-anchor" href="#_6-4-أخيرًا-احكم-على-الألم-والأولوية" aria-label="Permalink to “6.4 أخيرًا احكم على الألم والأولوية”">​</a></h3><p>لا تحتاج إلى السؤال مباشرة &quot;هل يؤلمك&quot;، يمكنك الحكم من التفاصيل:</p><ul><li>هل يواجه هذا كثيرًا</li><li>هل يتخذ بالفعل إجراءات نشطة للتعويض</li><li>هل هو مستعد بالفعل لدفع التكاليف من أجل هذا</li><li>هل يُظهر مشاعر واضحة عند الحديث عن هذا الأمر</li></ul><p>كل هذه أكثر فائدة من سؤال &quot;هل هذه نقطة ألم بالنسبة لك&quot;.</p><h2 id="_7-مثال-أكثر-اكتمالاً" tabindex="-1">7. مثال أكثر اكتمالاً <a class="header-anchor" href="#_7-مثال-أكثر-اكتمالاً" aria-label="Permalink to “7. مثال أكثر اكتمالاً”">​</a></h2><p>لنفترض أنك تريد صناعة منتج &quot;ذكاء اصطناعي يساعد طلاب الجامعات في تحسين سيرهم الذاتية&quot;.</p><h3 id="طريقة-خاطئة" tabindex="-1">طريقة خاطئة <a class="header-anchor" href="#طريقة-خاطئة" aria-label="Permalink to “طريقة خاطئة”">​</a></h3><p>تذهب لسؤال زميل:</p><blockquote><p>أريد صناعة أداة ذكاء اصطناعي لتحسين السيرة الذاتية، ما رأيك؟<br> إذا كانت تستطيع تعديل السيرة الذاتية تلقائيًا وفقًا للوظيفة، هل ستستخدمها؟</p></blockquote><p>في هذه الحالة، سيقول الطرف الآخر على الأرجح:</p><ul><li>يبدو جيدًا</li><li>أعتقد أنه سيكون مفيدًا</li><li>إذا كان مجانيًا سأجربه</li></ul><p>هذه الإجابات لا تساعدك تقريبًا في الحكم على مدى قوة الطلب.</p><h3 id="طريقة-أفضل" tabindex="-1">طريقة أفضل <a class="header-anchor" href="#طريقة-أفضل" aria-label="Permalink to “طريقة أفضل”">​</a></h3><p>يمكنك التغيير إلى:</p><blockquote><p>متى كانت آخر مرة عدّلت فيها سيرتك الذاتية؟<br> لماذا عدّلتها في ذلك الوقت؟<br> كيف عدّلتها؟<br> أي خطوة كانت الأصعب؟<br> هل طلبت من أحد أن يراجعها لك؟<br> هل أنفقت المال أو الكثير من الوقت على أمر السيرة الذاتية من قبل؟</p></blockquote><p>من خلال هذه الأسئلة، قد تحصل على معلومات مثل:</p><ul><li>الكثير من الناس لا يعرفون كيف يكتبون، بل لا يعرفون كيف يعيدون كتابة سيرتهم لتناسب وظائف مختلفة</li><li>أكثر ما يؤلمهم ليس التنسيق، بل &quot;عدم معرفة الخبرات التي تستحق الكتابة&quot;</li><li>يتأخرون ليس لأنهم كسالى، بل لأن تعديل السيرة الذاتية في كل مرة يستنزف طاقتهم</li><li>يستخدمون بالفعل نصائح الطلبة الأكبر سنًا ومواقع القوالب وأدوات الذكاء الاصطناعي ومساعدة الأصدقاء كحلول مؤقتة</li></ul><p>في هذه اللحظة، تكون أقرب بكثير إلى المشكلة الحقيقية.</p><h2 id="_8-كيفية-استخدام-اختبار-الأم-و-jtbd-معًا" tabindex="-1">8. كيفية استخدام اختبار الأم و JTBD معًا <a class="header-anchor" href="#_8-كيفية-استخدام-اختبار-الأم-و-jtbd-معًا" aria-label="Permalink to “8. كيفية استخدام اختبار الأم و JTBD معًا”">​</a></h2><p>إذا كان JTBD يساعدك في رؤية &quot;التقدم الذي يريد المستخدم تحقيقه&quot;، فإن اختبار الأم يعلمك:</p><p><strong>كيف تتأكد من خلال المقابلات أن هذا العمل موجود فعلاً.</strong></p><p>يمكنك استخدام الاثنين معًا:</p><ol><li>استخدم JTBD أولاً لافتراض عمل معين</li><li>ثم استخدم طريقة اختبار الأم لسؤال المستخدمين عن آخر تجربة حقيقية لهم</li><li>انظر ما إذا كان هذا العمل متكررًا وحقيقيًا ويستحق الأولوية فعلًا</li></ol><p>على سبيل المثال، افتراض JTBD الخاص بك هو:</p><blockquote><p>عندما أستعد لتقديم طلب تدريب، أريد تعديل سيرتي الذاتية القديمة بسرعة لتتناسب مع الوظيفة، حتى أتمكن من إكمال التقديم في أقرب وقت ممكن.</p></blockquote><p>يمكنك استخدام أسئلة بأسلوب اختبار الأم للتحقق:</p><ul><li>متى كانت آخر مرة قدمت فيها على تدريب؟</li><li>كيف عدّلت سيرتك الذاتية في ذلك الوقت؟</li><li>أي فقرة كانت الأصعب في كتابتها؟</li><li>بعد الانتهاء من التعديل، كيف تحكم على ما إذا كانت جيدة بما فيه الكفاية؟</li></ul><p>بهذه الطريقة، تتصل الطرق:</p><ul><li>JTBD يساعدك في تعريف فرضية الطلب</li><li>اختبار الأم يساعدك في التحقق من الفرضية من خلال المقابلات</li></ul><h2 id="_9-الأخطاء-الأكثر-شيوعًا-التي-يرتكبها-المبتدئون-عند-إجراء-مقابلات-المستخدمين" tabindex="-1">9. الأخطاء الأكثر شيوعًا التي يرتكبها المبتدئون عند إجراء مقابلات المستخدمين <a class="header-anchor" href="#_9-الأخطاء-الأكثر-شيوعًا-التي-يرتكبها-المبتدئون-عند-إجراء-مقابلات-المستخدمين" aria-label="Permalink to “9. الأخطاء الأكثر شيوعًا التي يرتكبها المبتدئون عند إجراء مقابلات المستخدمين”">​</a></h2><h3 id="_9-1-تحويل-المقابلة-إلى-عرض-تقديمي-للمنتج" tabindex="-1">9.1 تحويل المقابلة إلى عرض تقديمي للمنتج <a class="header-anchor" href="#_9-1-تحويل-المقابلة-إلى-عرض-تقديمي-للمنتج" aria-label="Permalink to “9.1 تحويل المقابلة إلى عرض تقديمي للمنتج”">​</a></h3><p>إذا تحدثت كثيرًا عن أفكارك الخاصة، سيبدأ الطرف الآخر بسهولة في مساعدتك بدلاً من إخبارك بالوضع الحقيقي.</p><h3 id="_9-2-جميع-أشخاص-المقابلة-من-المعارف" tabindex="-1">9.2 جميع أشخاص المقابلة من المعارف <a class="header-anchor" href="#_9-2-جميع-أشخاص-المقابلة-من-المعارف" aria-label="Permalink to “9.2 جميع أشخاص المقابلة من المعارف”">​</a></h3><p>المعارف ليسوا مستبعدون من التحدث معهم، لكنهم أكثر ميلاً لتشجيعك. تحتاج على الأقل إلى خلط بعض الأشخاص الأقرب إلى المستخدمين الحقيقيين، بدلاً من البحث فقط عن أشخاص يدعمونك.</p><h3 id="_9-3-متابعة-سريعة-للأسئلة-عن-الوظائف-في-وقت-مبكر-جدًا" tabindex="-1">9.3 متابعة سريعة للأسئلة عن الوظائف في وقت مبكر جدًا <a class="header-anchor" href="#_9-3-متابعة-سريعة-للأسئلة-عن-الوظائف-في-وقت-مبكر-جدًا" aria-label="Permalink to “9.3 متابعة سريعة للأسئلة عن الوظائف في وقت مبكر جدًا”">​</a></h3><p>إذا لم تكن قد فهمت المشكلة بعد، وبدأت في متابعة الأسئلة عن الأزرار والواجهات وتفاصيل الوظائف، فعادةً ما يكون ذلك دخولًا مبكرًا جدًا في مرحلة الحل.</p><h3 id="_9-4-اعتبار-جملة-سأستخدمه-كنتيجة-تحقق" tabindex="-1">9.4 اعتبار جملة &quot;سأستخدمه&quot; كنتيجة تحقق <a class="header-anchor" href="#_9-4-اعتبار-جملة-سأستخدمه-كنتيجة-تحقق" aria-label="Permalink to “9.4 اعتبار جملة &quot;سأستخدمه&quot; كنتيجة تحقق”">​</a></h3><p>المقابلة تساعدك على الأكثر في الحكم على الاتجاه، ولا تعني أن التحقق اكتمل. التحقق الحقيقي يعتمد في النهاية على ما إذا كان المستخدم مستعدًا لدفع تكاليف حقيقية، مثل الوقت وتكلفة التبديل وسلوك التجربة وحتى الدفع.</p><h3 id="_9-5-عدم-الترتيب-بعد-انتهاء-المقابلة" tabindex="-1">9.5 عدم الترتيب بعد انتهاء المقابلة <a class="header-anchor" href="#_9-5-عدم-الترتيب-بعد-انتهاء-المقابلة" aria-label="Permalink to “9.5 عدم الترتيب بعد انتهاء المقابلة”">​</a></h3><p>إذا تركتها بعد الانتهاء من التحدث، ستصبح المعلومات سريعًا انطباعات غامضة. من الأفضل الترتيب في أقرب وقت ممكن:</p><ul><li>المشاكل ذات التكرار العالي</li><li>الكلمات العاطفية في كلمات المستخدم الأصلية</li><li>البدائل الحالية</li><li>التكاليف المدفوعة بالفعل</li><li>أحكامك الجديدة الخاصة</li></ul><h2 id="_10-قائمة-أسئلة-يمكن-نسخها-واستخدامها-مباشرة" tabindex="-1">10. قائمة أسئلة يمكن نسخها واستخدامها مباشرة <a class="header-anchor" href="#_10-قائمة-أسئلة-يمكن-نسخها-واستخدامها-مباشرة" aria-label="Permalink to “10. قائمة أسئلة يمكن نسخها واستخدامها مباشرة”">​</a></h2><p>إذا كنت تريد البدء في أقرب وقت، إليك مجموعة من الأسئلة العامة بما فيه الكفاية.</p><h3 id="أسئلة-الافتتاح" tabindex="-1">أسئلة الافتتاح <a class="header-anchor" href="#أسئلة-الافتتاح" aria-label="Permalink to “أسئلة الافتتاح”">​</a></h3><ul><li>متى كانت آخر مرة واجهت فيها هذه المشكلة؟</li><li>ماذا حدث بالتحديد في ذلك الوقت؟</li></ul><h3 id="أسئلة-السلوك" tabindex="-1">أسئلة السلوك <a class="header-anchor" href="#أسئلة-السلوك" aria-label="Permalink to “أسئلة السلوك”">​</a></h3><ul><li>كيف تعاملت معها في ذلك الوقت؟</li><li>لماذا اخترت هذه الطريقة؟</li></ul><h3 id="أسئلة-التكلفة" tabindex="-1">أسئلة التكلفة <a class="header-anchor" href="#أسئلة-التكلفة" aria-label="Permalink to “أسئلة التكلفة”">​</a></h3><ul><li>كم من الوقت أو الجهد يستهلكه هذا الأمر عادةً؟</li><li>هل أنفقت المال من قبل لحله؟</li></ul><h3 id="أسئلة-البدائل" tabindex="-1">أسئلة البدائل <a class="header-anchor" href="#أسئلة-البدائل" aria-label="Permalink to “أسئلة البدائل”">​</a></h3><ul><li>هل جربت أدوات أو طرقًا أخرى؟</li><li>لماذا لم تستمر في استخدامها؟</li></ul><h3 id="أسئلة-الختام" tabindex="-1">أسئلة الختام <a class="header-anchor" href="#أسئلة-الختام" aria-label="Permalink to “أسئلة الختام”">​</a></h3><ul><li>إذا واجهت نفس المشكلة في المستقبل، ما الذي تعتقد أنه يجب أن يكون عليه الحل المثالي؟</li></ul><p>لاحظ أنه يمكن طرح سؤال الختام هذا، لكن من الأفضل وضعه في النهاية. لأنك تحتاج في البداية إلى الحصول على الحقائق، وليس الأمنيات.</p><h2 id="_11-ملخص" tabindex="-1">11. ملخص <a class="header-anchor" href="#_11-ملخص" aria-label="Permalink to “11. ملخص”">​</a></h2><p>أهم مساهمة لاختبار الأم ليست إعطائك مجموعة من مهارات &quot;التحدث بشكل أفضل&quot;، بل مساعدتك في بناء طريقة حكم أكثر وضوحًا:</p><ul><li>لا تثق بسرعة في مدح الآخرين لفكرتك</li><li>لا تعتبر &quot;إذا كان متاحًا سأستخدمه&quot; طلبًا حقيقيًا</li><li>لا تدع المقابلة تتحول إلى بحثك عن الموافقة</li></ul><p>المقابلات ذات القيمة الحقيقية يجب أن تعود قدر الإمكان إلى هذه الأشياء:</p><ul><li>آخر تجربة حقيقية للمستخدم</li><li>كيف يتعامل معها حاليًا</li><li>ما التكاليف التي دفعها بالفعل</li><li>في أي الأماكن يش بعدم الراحة بشكل واضح</li></ul><p>عندما تبدأ في السؤال بهذه الطريقة، المعلومات التي تحصل عليها، رغم أنها قد لا تكون لطيفة جدًا في بعض الأحيان، لكنها عادةً أكثر فائدة.<br> وعند صنع المنتج، <strong>الحقيقة المفيدة أهم دائمًا من التشجيع اللطيف.</strong></p><p><a id="mom-ai"></a></p><h2 id="_12-كيفية-استخدام-الذكاء-الاصطناعي-لمساعدتك-في-إجراء-مقابلات-المستخدمين" tabindex="-1"><a href="#top-mom">12. كيفية استخدام الذكاء الاصطناعي لمساعدتك في إجراء مقابلات المستخدمين</a> <a class="header-anchor" href="#_12-كيفية-استخدام-الذكاء-الاصطناعي-لمساعدتك-في-إجراء-مقابلات-المستخدمين" aria-label="Permalink to “12. كيفية استخدام الذكاء الاصطناعي لمساعدتك في إجراء مقابلات المستخدمين”">​</a></h2><p>اختبار الأم هو في جوهره طريقة &quot;للتحدث مع أشخاص حقيقيين&quot;، لذلك لا يمكن للذكاء الاصطناعي أن يحل محل المقابلات الحقيقية. لكن الذكاء الاصطناعي مناسب جدًا لمساعدتك قبل وأثناء وبعد المقابلة، خاصة في تقليل حاجز الدخول للمبتدئين.</p><h3 id="_12-1-دع-الذكاء-الاصطناعي-يساعدك-في-إعادة-كتابة-الأسئلة-السهلة-الفشل" tabindex="-1">12.1 دع الذكاء الاصطناعي يساعدك في إعادة كتابة الأسئلة &quot;السهلة الفشل&quot; <a class="header-anchor" href="#_12-1-دع-الذكاء-الاصطناعي-يساعدك-في-إعادة-كتابة-الأسئلة-السهلة-الفشل" aria-label="Permalink to “12.1 دع الذكاء الاصطناعي يساعدك في إعادة كتابة الأسئلة &quot;السهلة الفشل&quot;”">​</a></h3><p>الكثير من الناس يعرفون أنه لا ينبغي لهم سؤال &quot;ما رأيك في فكرتي&quot;، لكن بمجرد أن يتحدثون يعودون إلى هذه الجمل. يمكنك أولاً تسليم الأسئلة التي تستعد لطرحها إلى الذكاء الاصطناعي وجعله يساعدك في إعادة كتابتها:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>فيما يلي الأسئلة التي أريد طرحها عند إجراء مقابلات المستخدمين:</span></span>
<span class="line"><span>[ألصق أسئلتك]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>يرجى استخدام مبادئ اختبار الأم لمساعدتي في إعادة كتابتها:</span></span>
<span class="line"><span>1. احذف الأسئلة الرأيية</span></span>
<span class="line"><span>2. احذف الأسئلة التي تفترض المستقبل</span></span>
<span class="line"><span>3. حاول تغييرها إلى أسئلة تتمحور حول السلوكيات الحقيقية السابقة والبدائل القائمة والتكاليف المدفوعة</span></span>
<span class="line"><span>4. أخيرًا رتبها في قائمة من 8-10 أسئلة يمكن استخدامها مباشرة في المقابلات</span></span></code></pre></div><p>حتى الإدخال البسيط جدًا مقبول تمامًا:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>أريد أن أسأل المستخدمين:</span></span>
<span class="line"><span>1. ما رأيك في صناعة أداة ذكاء اصطناعي لتحسين السيرة الذاتية؟</span></span>
<span class="line"><span>2. هل ستستخدمها؟</span></span>
<span class="line"><span>3. هل أنت مستعد للدفع؟</span></span>
<span class="line"><span></span></span>
<span class="line"><span>يرجى مساعدتي في تغييرها إلى طريقة طرح أفضل.</span></span></code></pre></div><p>قد يكون الناتج المفيد من الذكاء الاصطناعي مثل هذا:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>الأسئلة المعاد كتابتها:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. متى كانت آخر مرة عدّلت فيها سيرتك الذاتية؟</span></span>
<span class="line"><span>2. لماذا عدّلتها في ذلك الوقت؟</span></span>
<span class="line"><span>3. كيف عدّلتها؟</span></span>
<span class="line"><span>4. أي خطوة استغرقت أكثر وقت؟</span></span>
<span class="line"><span>5. هل طلبت من أحد أن يراجعها لك؟</span></span>
<span class="line"><span>6. هل أنفقت المال أو الكثير من الوقت على تعديل السيرة الذاتية من قبل؟</span></span></code></pre></div><p>هذا الناتج مفيد جدًا لأنه يحول أسئلتك الأصلية &quot;التي تسأل عن الآراء&quot; مباشرة إلى أسئلة &quot;تسأل عن السلوكيات الحقيقية&quot;.</p><h3 id="_12-2-دع-الذكاء-الاصطناعي-يساعدك-في-إنشاء-خطط-مقابلات-مختلفة-لكل-فئة" tabindex="-1">12.2 دع الذكاء الاصطناعي يساعدك في إنشاء خطط مقابلات مختلفة لكل فئة <a class="header-anchor" href="#_12-2-دع-الذكاء-الاصطناعي-يساعدك-في-إنشاء-خطط-مقابلات-مختلفة-لكل-فئة" aria-label="Permalink to “12.2 دع الذكاء الاصطناعي يساعدك في إنشاء خطط مقابلات مختلفة لكل فئة”">​</a></h3><p>نفس الاتجاه، مع مجموعات مختلفة من الناس، ستكون نقاط التركيز في المقابلة مختلفة. على سبيل المثال، الطلاب ومديري الموارد البشرية والعاملون المستقلون يهتمون بأشياء مختلفة تمامًا. يمكنك أن تطلب من الذكاء الاصطناعي إنشاء نسخة من خطة المقابلة لكل فئة:</p><ul><li>للمستخدمين الجدد، التركيز على فهم آخر تجربة حقيقية</li><li>للمستخدمين المكثفين، التركيز على فهم البدائل وشدة الألم</li><li>للمستخدمين الدافعين، التركيز على فهم ما إذا كانوا قد دفعوا تكاليف بالفعل من أجل هذا</li></ul><p>بهذه الطريقة ستكون لديك إيقاع أفضل عند التحدث الفعلي، بدلاً من طرح نفس مجموعة الأسئلة على كل شخص.</p><p>على سبيل المثال، يمكنك الإدخال مباشرة هكذا:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>سأتحدث مع نوعين من الأشخاص:</span></span>
<span class="line"><span>1. طلاب الجامعات الذين يبحثون عن تدريب لأول مرة</span></span>
<span class="line"><span>2. طلبة أكبر سنًا سبق لهم مراجعة العديد من السير الذاتية للآخرين</span></span>
<span class="line"><span></span></span>
<span class="line"><span>يرجى إعطائي خطة مقابلة لكل فئة، 6 أسئلة لكل منها.</span></span></code></pre></div><p>قد يكون ناتج الذكاء الاصطناعي:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>لطلاب الجامعات:</span></span>
<span class="line"><span>1. متى كانت آخر مرة قدمت فيها على تدريب؟</span></span>
<span class="line"><span>2. أي خطوة كانت الأصعب في ذلك الوقت؟</span></span>
<span class="line"><span>3. كيف تعرف ما إذا كانت سيرتك الذاتية يمكن تقديمها؟</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>للطلبة الأكبر سنًا:</span></span>
<span class="line"><span>1. متى كانت آخر مرة ساعدت فيها شخصًا في مراجعة سيرته الذاتية؟</span></span>
<span class="line"><span>2. ما أكثر المشاكل وضوحًا التي تراها بشكل متكرر؟</span></span>
<span class="line"><span>3. ما هي الخطوة التي يواجه فيها الطلاب الأصغر سنًا أكبر صعوبة؟</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>بهذه الطريقة، لا تحتاج إلى كتابة الأسئلة من الصفر، وسيكون التحضير للمقابلة أسهل بكثير.</p><h3 id="_12-3-دع-الذكاء-الاصطناعي-يساعدك-في-ترتيب-سجلات-المقابلات" tabindex="-1">12.3 دع الذكاء الاصطناعي يساعدك في ترتيب سجلات المقابلات <a class="header-anchor" href="#_12-3-دع-الذكاء-الاصطناعي-يساعدك-في-ترتيب-سجلات-المقابلات" aria-label="Permalink to “12.3 دع الذكاء الاصطناعي يساعدك في ترتيب سجلات المقابلات”">​</a></h3><p>بعد انتهاء المقابلات، أكثر المشاكل شيوعًا ليست &quot;عدم وجود معلومات&quot;، بل &quot;المعلومات مشتتة جدًا&quot;. الذكاء الاصطناعي مناسب جدًا لمساعدتك في ترتيب المحادثات المجزأة في ملاحظات منظمة:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>فيما يلي سجلات مقابلاتي مع 3 مستخدمين.</span></span>
<span class="line"><span>يرجى الترتيب من منظور اختبار الأم:</span></span>
<span class="line"><span>1. أي المحتويات هي حقائق وأيها مجرد آراء</span></span>
<span class="line"><span>2. ما هو آخر سلوك حقيقي للمستخدم</span></span>
<span class="line"><span>3. ما هي البدائل الحالية</span></span>
<span class="line"><span>4. ما هي تكاليف الوقت والمال أو الجهد التي دفعها المستخدم بالفعل</span></span>
<span class="line"><span>5. أي المشاكل تم ذكرها بشكل متكرر</span></span>
<span class="line"><span>6. أي العبارات تبدو إيجابية لكن الأدلة عليها غير كافية</span></span></code></pre></div><p>هذه الخطوة ذات قيمة خاصة لأنها تساعدك في فصل المحتوى &quot;الذي يبدو جيدًا&quot; عن المحتوى &quot;الذي يدعم الحكم فعلاً&quot;.</p><p>يمكن أن يكون الإدخال البسيط:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>هذا سجل محادثتي مع مستخدم:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- قالت إذا كان هناك أداة فستجربها على الأرجح</span></span>
<span class="line"><span>- الأسبوع الماضي قضيت ليلة كاملة في تعديل سيرتها الذاتية</span></span>
<span class="line"><span>- تعتمد حاليًا بشكل أساسي على الأصدقاء لمراجعة سيرتها</span></span>
<span class="line"><span>- قالت أن أصعب شيء هو عدم معرفة ما الذي يجب تعديله حتى يكون جاهزًا للتقديم</span></span>
<span class="line"><span></span></span>
<span class="line"><span>يرجى مساعدتي في التمييز بين الآراء والحقائق.</span></span></code></pre></div><p>قد يكون ناتج الذكاء الاصطناعي:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>الآراء:</span></span>
<span class="line"><span>- إذا كان هناك أداة فستجربها على الأرجح</span></span>
<span class="line"><span></span></span>
<span class="line"><span>الحقائق:</span></span>
<span class="line"><span>- الأسبوع الماضي قضيت ليلة كاملة في تعديل السيرة الذاتية</span></span>
<span class="line"><span>- البديل الحالي هو طلب مساعدة الأصدقاء لمراجعتها</span></span>
<span class="line"><span>- أصعب نقطة هي عدم معرفة متى تعتبر &quot;جاهزة للتقديم&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>النقاط التي يمكن استخدامها للحكم على المتطلبات:</span></span>
<span class="line"><span>- هذه المشكلة حدثت مؤخرًا</span></span>
<span class="line"><span>- المستخدم دفع بالفعل تكاليف وقت واضحة</span></span>
<span class="line"><span>- الحل الحالي يعتمد على الآخرين وغير مستقر</span></span></code></pre></div><p>هذا الناتج يخبر المبتدئ بشكل حدسي: أي الكلمات يمكن استخدامها للحكم وأيها يمكن الاستماع إليها فقط.</p><h3 id="_12-4-دع-الذكاء-الاصطناعي-يقوم-بجولة-خفيفة-من-البحث-على-الإنترنت-أولاً" tabindex="-1">12.4 دع الذكاء الاصطناعي يقوم بجولة خفيفة من البحث على الإنترنت أولاً <a class="header-anchor" href="#_12-4-دع-الذكاء-الاصطناعي-يقوم-بجولة-خفيفة-من-البحث-على-الإنترنت-أولاً" aria-label="Permalink to “12.4 دع الذكاء الاصطناعي يقوم بجولة خفيفة من البحث على الإنترنت أولاً”">​</a></h3><p>إذا لم تبدأ المقابلات بعد، يمكنك أن تطلب من الذكاء الاصطناعي القيام ببعض الأبحاث الخارجية الخفيفة جدًا، مثل:</p><ul><li>في المجتمعات العامة، كيف يشتكي الناس مؤخرًا من هذه المشكلة</li><li>ما أكثر شيء يتم انتقاده في الأدوات الحالية</li><li>هل دفع المستخدمون بالفعل مقابل مشاكل مشابهة</li><li>ما هي البدائل الموجودة في السوق</li></ul><p>هذه المعلومات لا يمكنها أن تحل محل المقابلات الحقيقية، لكنها تساعدك على الدخول في الحالة بشكل أسرع ومعرفة من أين تبدأ الأسئلة.</p><p>على سبيل المثال، يمكن أن يكون الإدخال البسيط:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>يرجى البحث من أجلي:</span></span>
<span class="line"><span>&quot;ما الذي يشتكي منه طلاب الجامعات أكثر شيء عند تعديل سيرهم الذاتية&quot;</span></span>
<span class="line"><span>ساعدني في ترتيب 5 شكاوى الأكثر شيوعًا، واكتبها بلغة بسيطة.</span></span></code></pre></div><p>قد يكون ناتج الذكاء الاصطناعي:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>الشكاوى الشائعة:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. لا أعرف ما الذي يجب كتابته في السيرة الذاتية</span></span>
<span class="line"><span>2. يجب تعديلها لكل وظيفة، الأمر متعب جدًا</span></span>
<span class="line"><span>3. عدّلت العديد من النسخ لكنني لست متأكدًا من جودتها</span></span>
<span class="line"><span>4. لا يوجد أحد يعطيني ملاحظات موثوقة</span></span>
<span class="line"><span>5. أشعر دائمًا أنني لست مستعدًا بعد، لذلك أؤجل باستمرار</span></span></code></pre></div><p>قيمة هذه النتيجة تكمن في أنها ستسهل عليك العثور على نقطة دخول للمقابلة.</p><h3 id="_12-5-دع-الذكاء-الاصطناعي-يلعب-دور-مدرب-مراجعة-المقابلات" tabindex="-1">12.5 دع الذكاء الاصطناعي يلعب دور &quot;مدرب مراجعة المقابلات&quot; <a class="header-anchor" href="#_12-5-دع-الذكاء-الاصطناعي-يلعب-دور-مدرب-مراجعة-المقابلات" aria-label="Permalink to “12.5 دع الذكاء الاصطناعي يلعب دور &quot;مدرب مراجعة المقابلات&quot;”">​</a></h3><p>يمكنك أيضًا أن تعطي سجل مقابلة مستخدم أنجزتها للتو للذكاء الاصطناعي وجعله ينتقدك:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>فيما يلي سجل مقابلة مستخدم قمت بها.</span></span>
<span class="line"><span>يرجى مراجعتها من منظور اختبار الأم:</span></span>
<span class="line"><span>1. أي الأسئلة طرحتها بشكل يشبه البحث عن الموافقة</span></span>
<span class="line"><span>2. أي الأسئلة تحمل توجيهًا واضحًا</span></span>
<span class="line"><span>3. أي الأماكن كان يمكن فيها متابعة السؤال عن الحقائق</span></span>
<span class="line"><span>4. إذا جاءت مرة أخرى، كيف يمكن طرح هذه المحادثة بشكل أفضل</span></span></code></pre></div><p>هذا مفيد جدًا للمبتدئين، لأنك ستطور بسرعة حساسية تجاه &quot;هل أنا أجمع الأدلة أم أجمع التشجيع&quot;.</p><h2 id="📚-الواجبات" tabindex="-1">📚 الواجبات <a class="header-anchor" href="#📚-الواجبات" aria-label="Permalink to “📚 الواجبات”">​</a></h2><p>يرجى إكمال الواجبات التالية بناءً على المحتوى أعلاه:</p><ol><li>اختر اتجاه منتج تريد صناعته مؤخرًا، واكتب أولاً 5 أسئلة &quot;سهلة الفشل&quot; كنت ستطرحها في الأصل</li><li>أعد كتابة هذه الأسئلة الخمسة لتصبح أكثر توافقًا مع أسلوب اختبار الأم</li><li>ابحث عن 3 مستخدمين محتملين، واسأل على الأقل مرة واحدة &quot;متى كانت آخر مرة واجهت فيها هذه المشكلة&quot;</li><li>بعد انتهاء المقابلة، رتب 4 فئات من المعلومات: السلوكيات الحقيقية، البدائل، التكاليف المدفوعة، الصعوبات المتكررة</li></ol><h2 id="قراءة-موسعة" tabindex="-1">قراءة موسعة <a class="header-anchor" href="#قراءة-موسعة" aria-label="Permalink to “قراءة موسعة”">​</a></h2><ul><li><a href="https://momtestbook.com/" target="_blank" rel="noreferrer">موقع اختبار الأم الرسمي</a></li><li><a href="https://www.robfitz.com/the-mom-test/" target="_blank" rel="noreferrer">روب فيتزباتريك: اختبار الأم</a></li></ul>`,185))])}}});export{k as __pageData,g as default};
